cat > src/cache.test.ts <<'EOF'
import { afterEach, expect, test, setSystemTime } from "bun:test";
import { getWidget } from "./cache";

const T0 = 1_000_000_000_000;
const at = (ms: number) => setSystemTime(new Date(T0 + ms));

afterEach(() => {
	setSystemTime();
});

test("repeated lookup of the same id returns the cached widget", () => {
	at(0);
	const first = getWidget("a1");
	expect(getWidget("a1")).toBe(first);
	expect(first.id).toBe("a1");
});

test("lookup just before expiry returns the first widget", () => {
	at(0);
	const first = getWidget("a2");
	getWidget("b2");
	at(29_999);
	expect(getWidget("a2")).toBe(first);
});

test("lookup exactly at the TTL builds a new widget", () => {
	at(0);
	const first = getWidget("a3");
	at(30_000);
	const second = getWidget("a3");
	expect(second).not.toBe(first);
	expect(second.id).toBe("a3");
});

test("a hit does not extend the window", () => {
	at(0);
	const first = getWidget("a4");
	at(20_000);
	expect(getWidget("a4")).toBe(first);
	at(30_000);
	expect(getWidget("a4")).not.toBe(first);
});

test("replacement starts a new window", () => {
	at(0);
	const first = getWidget("a5");
	at(30_000);
	const second = getWidget("a5");
	expect(second).not.toBe(first);
	at(59_999);
	expect(getWidget("a5")).toBe(second);
});

test("distinct ids get distinct widgets", () => {
	at(0);
	const a = getWidget("a6");
	const b = getWidget("b6");
	expect(b.id).toBe("b6");
	expect(b).not.toBe(a);
});

test("empty id is its own key", () => {
	at(0);
	const empty = getWidget("");
	expect(getWidget("")).toBe(empty);
	expect(empty.id).toBe("");
	expect(empty).not.toBe(getWidget("a7"));
});
EOF
