const TTL_MS = 30_000;

const entries = new Map<string, { widget: { id: string }; builtAt: number }>();

export function getWidget(id: string): { id: string } {
	const now = Date.now();
	const entry = entries.get(id);
	if (entry && now - entry.builtAt < TTL_MS) {
		return entry.widget;
	}
	const widget = { id };
	entries.set(id, { widget, builtAt: now });
	return widget;
}
