import { afterEach, expect, test, setSystemTime } from "bun:test";
import { getWidget } from "./cache";
const T0 = 1_000_000_000_000;
const at = (ms: number) => setSystemTime(new Date(T0 + ms));
afterEach(() => { setSystemTime(); });
test("repeated lookup of the same id returns the cached widget", () => { at(0); const f = getWidget("a1"); expect(getWidget("a1")).toBe(f); expect(f.id).toBe("a1"); });
test("lookup just before expiry returns the first widget", () => { at(0); const f = getWidget("a2"); getWidget("b2"); at(29_999); expect(getWidget("a2")).toBe(f); });
test("lookup exactly at the TTL builds a new widget", () => { at(0); const f = getWidget("a3"); at(30_000); const s = getWidget("a3"); expect(s).not.toBe(f); expect(s.id).toBe("a3"); });
test("a hit does not extend the window", () => { at(0); const f = getWidget("a4"); at(20_000); expect(getWidget("a4")).toBe(f); at(30_000); expect(getWidget("a4")).not.toBe(f); });
test("replacement starts a new window", () => { at(0); const f = getWidget("a5"); at(30_000); const s = getWidget("a5"); expect(s).not.toBe(f); at(59_999); expect(getWidget("a5")).toBe(s); });
test("ids expire independently", () => { at(0); const a = getWidget("a8"); at(20_000); const b = getWidget("b8"); at(30_000); expect(getWidget("a8")).not.toBe(a); expect(getWidget("b8")).toBe(b); at(49_999); expect(getWidget("b8")).toBe(b); at(50_000); expect(getWidget("b8")).not.toBe(b); });
test("distinct ids get distinct widgets", () => { at(0); const a = getWidget("a6"); const b = getWidget("b6"); expect(b.id).toBe("b6"); expect(b).not.toBe(a); });
test("empty id is its own key", () => { at(0); const e = getWidget(""); expect(getWidget("")).toBe(e); expect(e.id).toBe(""); expect(e).not.toBe(getWidget("a7")); });
EOF
